INSERT INTO "PointPricingRule" ("id","workspaceId","action","pointCost","enabled","createdById","reason") SELECT 'system-pricing-shipment-create',NULL,'shipments.create',5,TRUE,'system','Cloudie default platform pricing' WHERE NOT EXISTS (SELECT 1 FROM "PointPricingRule" WHERE "action"='shipments.create' AND "workspaceId" IS NULL);
INSERT INTO "PointPricingRule" ("id","workspaceId","action","pointCost","enabled","createdById","reason") SELECT 'system-pricing-shipment-update',NULL,'shipments.tracking_update',1,TRUE,'system','Cloudie default platform pricing' WHERE NOT EXISTS (SELECT 1 FROM "PointPricingRule" WHERE "action"='shipments.tracking_update' AND "workspaceId" IS NULL);
